 const shadowCanvas=document.createElement('canvas');shadowCanvas.width=128;shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(64,64,3,64,64,64);gradient.addColorStop(0,'rgba(53,65,37,.22)');gradient.addColorStop(.3,'rgba(53,65,37,.12)');gradient.addColorStop(1,'rgba(53,65,37,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);
 shadow=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false,opacity:.7}));shadow.scale.set(470,110,1);shadow.position.set(0,-160,-180);scene.add(shadow);
 resize();new ResizeObserver(resize).observe($('stage'));
 const surface=renderer.domElement;let points=new Map(),lastPinch=0,oldX=0,oldY=0;
 surface.addEventListener('pointerdown',e=>{points.set(e.pointerId,[e.clientX,e.clientY]);surface.setPointerCapture(e.pointerId);oldX=e.clientX;oldY=e.clientY;dragging=true;});
 surface.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,[e.clientX,e.clientY]);if(points.size===2){const p=[...points.values()],d=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);if(lastPinch)userZoom=T.MathUtils.clamp(userZoom*d/lastPinch,.5,2.4);lastPinch=d;}else{azimuth+=(e.clientX-oldX)*.008;tilt=T.MathUtils.clamp(tilt+(e.clientY-oldY)*.008,-2,2);}oldX=e.clientX;oldY=e.clientY;dirty=true;});
 const end=e=>{points.delete(e.pointerId);lastPinch=0;dragging=points.size>0;};surface.addEventListener('pointerup',end);surface.addEventListener('pointercancel',end);surface.addEventListener('lostpointercapture',end);
